def backfill_initial_rates(apps, schema_editor):
    db_alias = schema_editor.connection.alias
    ContributionType = apps.get_model('treasury', 'ContributionType')
    ContributionTypeRate = apps.get_model('treasury', 'ContributionTypeRate')
    ClubSettings = apps.get_model('clubs', 'ClubSettings')
    timezones = dict(ClubSettings.objects.using(db_alias).values_list('club_id', 'timezone'))
    rates = []

    for contribution_type in ContributionType.all_objects.using(db_alias).exclude(amount__isnull=True).iterator():
        try:
            club_timezone = ZoneInfo(timezones.get(contribution_type.club_id) or 'UTC')
        except (ZoneInfoNotFoundError, ValueError):
            club_timezone = dt_timezone.utc
        created_at = contribution_type.created_at
        if created_at.tzinfo is None:
            created_at = created_at.replace(tzinfo=dt_timezone.utc)
        local_created_at = created_at.astimezone(club_timezone)
        rates.append(
            ContributionTypeRate(
                club_id=contribution_type.club_id,
                contribution_type_id=contribution_type.pk,
                amount=contribution_type.amount,
                effective_from=date(local_created_at.year, local_created_at.month, 1),
                created_at=contribution_type.created_at,
                created_by_id=contribution_type.created_by_id,
            )
        )

    ContributionTypeRate.all_objects.using(db_alias).bulk_create(rates, batch_size=500)


